-- Adds English translations for the trainings (exercises) table.
-- Safe to run multiple times: columns are added IF NOT EXISTS, UPDATEs are idempotent.

ALTER TABLE public.trainings ADD COLUMN IF NOT EXISTS title_en text;
ALTER TABLE public.trainings ADD COLUMN IF NOT EXISTS description_en text;
ALTER TABLE public.trainings ADD COLUMN IF NOT EXISTS instructions_en text[];

UPDATE public.trainings SET title_en = 'Corner Threes', description_en = 'Corner three — the highest shooting percentage from any spot beyond the arc (the line is 0.5m shorter there). Klay Thompson, Duncan Robinson, and Joe Harris built million-dollar contracts purely on the corner. Your work today is their work, every day, for 10 years.', instructions_en = ARRAY['Position: both corners, foot behind the line — don''t step on it, refs notice.', 'Squared up to the rim, not the backboard — different angle than a midrange bank shot.', 'Catch & shoot: the ball goes straight to the shot pocket in one motion, no hand adjustments.', 'Mechanics: legs-hips-arm, the ball leaves your hand before you land (no fading).', 'Right side: 25 shots. Left side: 25 shots. Plus 25 from the right "short corner" (a deeper angle).', 'Target: 15/25 (60%) = elite-level corner shooter at NCAA/Europe level.', 'Movement test: sprint from the slot → catch & shoot from the corner. 10 attempts, target 6/10.', 'Finish: 10 from the "wing extension" (a few steps beyond the corner) — more game-realistic.'] WHERE id = '36718a6e-eae7-4f44-90a1-119134f5d51f';
UPDATE public.trainings SET title_en = 'Midrange Twos', description_en = 'Spot-up midrange from the 45° angle — a foundational shot that built the careers of DeRozan, KD, and Khris Middleton. Too often neglected in the three-point era, yet still the most repeatable shot in your arsenal, regardless of the defense.', instructions_en = ARRAY['Position: 4–5m from the basket, 45° angle to the backboard (between the corner and the top of the key).', 'Squared up: shoulders, hips, and feet pointed straight at the rim.', 'Catch & shoot: the ball goes to the shot pocket in one motion — no extra dribble.', '20 shots from the right × 20 from the left × 10 days = a built-in habit.', 'Target: 12/20 (60%) — that''s the threshold for a "reliable midrange shooter".', 'Focus on the arc: too flat a line means no soft landing — correct it on every shot.', 'After every set of 20, shoot 5 free throws — reset your rhythm and focus.', 'Finish: the last 10 shots on the clock — 60 seconds for 10 attempts (pressure simulation)..'] WHERE id = '63752e92-9cf7-469d-bddc-99730c6b7f5a';
UPDATE public.trainings SET title_en = 'Footwork — Mamba Mentality', description_en = 'Kobe Bryant''s footwork. Pivot, jab step, rip through, drop step — four moves Kobe drilled for 20 years in every individual workout. Footwork is the difference between a blocked shot and a clean release. Without it, the best shooting mechanics mean nothing.', instructions_en = ARRAY['Front pivot R + L: 15 reps each side. Pivot foot stays still, the other sweeps a half-circle.', 'Reverse pivot R + L: 15 reps each side. Rotate through your back, body protected.', 'Jab step + shot: 15 reps. Fake step forward (12–15cm), pull back, shoot from the set position.', 'Jab step + drive: 15 reps. Fake step forward, second step explosively in the chosen direction.', 'Rip through (move the ball from high to low across your torso): 15 reps each side. Low tempo + ball protection.', 'Drop step after a post-up: 15 reps. Foot behind the defender, open the hip, finish at the rim.', 'Up and under: 15 reps. Pump fake, step under the defender''s arm, soft finish.', 'Combo: jab + cross + drive: 15 reps each side. Full game-speed sequence.'] WHERE id = 'c77b12de-b011-4fdd-8320-3278b9556cab';
UPDATE public.trainings SET title_en = 'Screen Setting & Using', description_en = 'A good screen is the most valuable thing you can do for your team without the ball. PJ Tucker, Draymond Green, Dillon Brooks — technically limited players who became essential through how they set and use screens. It''s a skill NBA scouts value more than shooting.', instructions_en = ARRAY['Screen-setting stance: wide base (shoulder-width feet), arms crossed over the chest, body like steel.', 'Contact with the defender: make contact, but don''t move (illegal screen). Stand still for 1 second before contact.', 'Angle setting: set the screen at a 45° angle to the defender''s path — that''s maximum effectiveness.', 'Screen and slip: set the screen, but roll to the rim before the defender arrives. 15 reps.', 'Screen and pop: set the screen, step back, ready for catch & shoot from distance. 15 reps.', 'Using a screen (offense): read the screen''s direction, brush shoulder-to-shoulder past the defender.', 'Reject the screen: when the defender lazily approaches the screen, go the other way — drive free. 10 reps.', 'Film study: 30 minutes of Draymond Green screening for Curry — the best screener-roller duo in NBA history.'] WHERE id = 'a9fcba49-2147-44aa-9c08-97f53e607eff';
UPDATE public.trainings SET title_en = 'Pick & Roll Reads', description_en = 'Pick & roll is the most-used play in the NBA — 27% of all possessions start with a PnR. Chris Paul, Steph Curry, Damian Lillard — they all built careers on reading these two decisions: split, switch, drop, hedge. You need to react to every one.', instructions_en = ARRAY['Drop coverage (center retreats): attack = pull-up midrange or dribble three. 10 reps each side.', 'Switch (defenders swap): attack = post-up the smaller defender or kick-out to the roller. 10 reps.', 'Hedge / Show (the big jumps out on defense): attack = pocket pass to the roller, or pull away after the hedge. 10 reps.', 'Ice / Sideline shade (closing off the direction): attack = reject the screen (go the other way) + attack the lane. 10 reps.', 'Reading drill: a partner simulates 1 of 4 defensive reactions, you read it and make the right decision. 20 reps, randomized.', 'Rolling vs. popping: after using the screen, read the screener — rolling to the rim or popping for three. 15 reps.', 'Pace: a slowed-down PnR = a better decision. Remember — Chris Paul plays in "slow motion".', 'Study film: 30 minutes of Steph Curry pick & rolls or Damian Lillard PnR — watch when he pulls away, when he passes.'] WHERE id = '12f4cc65-89e1-48e3-ac87-d4ab83c708aa';
UPDATE public.trainings SET title_en = 'Speed & Agility Ladder', description_en = 'The agility ladder — equipment found at every NBA performance facility. Builds foot speed, rhythm, and the leg coordination needed for crossovers, defense, and changes of direction. 10 minutes of work = months of in-game improvement.', instructions_en = ARRAY['Set up a 10-rung ladder on a flat surface.', 'In-in-out-out (two feet in the box, two outside): 5 passes. Fast tempo, small steps.', 'High knees through the ladder: 5 passes. Knee to hip, one touch per box.', 'Lateral shuffle (side to side): 5 passes each direction. No crossing allowed.', 'Ickey shuffle (1-2-1): 5 passes. Left-right into the box, right outside; then reverse.', 'Single-leg hop: 3 passes each leg. Explosive hop on one leg.', 'Crossover step: 5 passes each direction. Cross your feet in every box.', 'Carioca: 3 passes each side. Cross-step in front/behind in a dancing rhythm.', 'Tempo progression: first set controlled (technique), second at 90% speed, third full speed.'] WHERE id = 'a7112f80-58fd-4eb3-83c9-029118597964';
UPDATE public.trainings SET title_en = 'Finishing at the Rim', description_en = 'Finishing at the rim through contact — the art of a true scorer. Giannis, Embiid, Bam Adebayo, Ja Morant — they all have an arsenal of 8–10 ways to "finish through contact". This is where you earn the highest shooting percentage in all of basketball.', instructions_en = ARRAY['Standard layup R/L: 10 from each side, knee high, ball soft off the glass.', 'Reverse layup: 10 attempts — drive under the basket, finish on the other side. The glass protects you from the block.', 'Euro step: 5 attempts R, 5 L — one step one way, the next the opposite. A strong shift in direction.', 'Floater scoop: 5 attempts R, 5 L — a low scoop shot under contact.', 'Up-and-under: 5 attempts — pump fake on the defender, step under their arm, soft finish.', 'Contact finish: a partner with a pad hits your side on every layup — simulating a foul.', 'Spin finish: 5 attempts R, 5 L — spin off the shoulder at the right tempo, soft mechanics.', 'Total: ~70 attempts across variations. Goal: 70%+ on "easier" shots (layup), 50%+ on "hard" ones (euro/floater).'] WHERE id = '29918de5-0dbd-4d43-a6ae-bb015fea2e70';
UPDATE public.trainings SET title_en = 'Full Court Sprint Intervals', description_en = 'Simulating game rhythm — full-court sprint, jog back. Mimics transition offense and recovery defense, where 60% of points happen in modern NBA. Builds the exact aerobic-glycolytic system you need in the 4th quarter.', instructions_en = ARRAY['8-minute warmup: light jog + dynamic stretches + 3 progressive sprints.', 'Full court sprint (28m) at max speed — about 4–5 seconds.', 'Jog back (28m) at recovery pace — about 12–15 seconds.', 'Combined cycle = 20 seconds. No rest between cycles.', 'Complete 20 cycles (10 minutes of continuous work).', 'Goal: every sprint at a consistent time (max 10% difference between the 1st and the 20th).', 'Cooldown: 5 minutes of walking + static calf and hamstring stretches.', 'Track progress: log your average sprint time — aim to shave off 0.1–0.2s every week.'] WHERE id = '84c8f763-2f17-4a99-a8b1-bd0c8315b8b9';
UPDATE public.trainings SET title_en = 'Passing & Vision — Creating Offense', description_en = 'The best point guards see the court 2 seconds before everyone else. LeBron, Magic, Luka — their assists are the result of thousands of hours spent on passing and reading space. Without this skill you''re only a scorer; with it — a facilitator.', instructions_en = ARRAY['Chest pass against a wall: 50 reps each hand. Power the pass, control the ball landing in the same spot.', 'Bounce pass against a wall: 30 reps. Bounce 2/3 of the distance from the wall — the most common mistake is bouncing too close.', 'Overhead pass against a wall: 30 reps. From above your head, elbows close to your body.', 'No-look pass (eyes one way, pass the other): 20 reps each side. Requires peripheral coordination.', 'Wrap-around pass (behind-the-back pass): 15 reps each hand. Practice against a wall first.', 'Pocket pass (low pass near the basket): 20 reps. Simulate a pick & roll — skip pass to the rolling big.', 'Vision drill: dribble while a partner holds up 1, 2, or 3 fingers in your peripheral vision. Call out the number out loud. 60 seconds.', 'Game-speed kick-out: drive to the basket + last second + skip pass to the "corner" (target: a cone 6m away). 15 reps.'] WHERE id = 'afc3f1ca-74bc-4678-b3f0-31caafee6d46';
UPDATE public.trainings SET title_en = 'Mental Toughness', description_en = 'NBA-level mental game. Five daily protocols that Kobe, Jordan, and LeBron treated as non-negotiable — discipline, breathing, journaling, and exposure to discomfort.', instructions_en = ARRAY['Morning pre-mortem (3 min): mentally write down the 3 worst-case scenarios for today/your workout and what you''ll do in each — it switches off the autopilot of fear.', 'Box breathing 4-4-4-4 (4 min): inhale 4s, hold 4s, exhale 4s, hold 4s, 16 cycles. Resets your nervous system — Navy SEAL standard.', 'Cold exposure (2 min): end your shower with 60–90s of cold water, breathe through your nose. Builds the tolerance to discomfort you''ll use in the 4th quarter.', 'Decision count: one decision today against the easier option (get up on time, finish the set, take a free throw with the full routine). Write it down.', 'Evening journal (5 min): one thing you did well, one concrete thing to improve, one thing you''re grateful for. Small data, months of difference.'] WHERE id = 'ab70a7ff-844b-4215-9737-332c4a053288';
UPDATE public.trainings SET title_en = 'Lateral Quickness — Defense & Movement', description_en = 'Lateral speed is the foundation of both defense and offense. Steph Curry is famous for his threes, but his lateral movement (per NBA tracking systems) is top 5 in the league — that''s why he can shake any defender. Without lateral agility there''s no elite defense or crossovers.', instructions_en = ARRAY['Defensive slide (50% speed) across the full width of the court: 5 passes each way.', 'Defensive slide (90% speed): 5 passes each way. Low stance, feet flat.', 'Lane agility drill (NBA Combine): 8 reps. Sprint to the free-throw line, lateral slide, sprint backward, slide the other way.', 'Lateral cone touch: 4 cones 3m apart. Touch each one with a lateral slide, change direction after each. 8 reps.', 'Reactive lateral: a partner points a direction with their hand, you react with a 3m lateral slide. 15 reps.', 'Closeout drill: sprint 5m + the last 3 steps in a defensive slide with chopsticks (tiny steps).', 'Crab walk (lateral with the ball in your hands): 20m each direction. Simulates defending while holding your pivot foot.', 'Finish: 5 minutes of foam rolling the IT band — the most loaded area in lateral movement.'] WHERE id = '326aaf15-f1de-4b6f-9480-e9eeb6fbf0a1';
UPDATE public.trainings SET title_en = 'Reactive Agility', description_en = 'Real sport is reaction, not a planned move. You train your response to an unexpected stimulus — like a defender changing direction right before your crossover. Without this, every other agility drill is just theory.', instructions_en = ARRAY['Mirror drill: stand facing a partner 3m away, they move randomly laterally, you mirror them. 5 rounds of 30 seconds.', 'Color reaction sprint: a partner holds 4 colored cones. They shout a color, you sprint to it. 10 reps.', 'Hand signal lateral: a partner points left/right with their hand, you react with a 3m defensive slide. 15 reps.', 'Visual cue sprint: a partner stands 5m in front of you, raises a hand = sprint, lowers it = you stop. 20 reps.', 'Lightning round: combine with the ball — partner points a direction + calls a command (dribble, pass, shoot). 30 seconds non-stop.', 'Tennis ball drop: a partner holds a tennis ball at arm''s length, drops it, you catch it before the second bounce. 10 reps.', 'Sprint-and-react: sprint 5m to a partner, they randomly point a direction (R/L/back) — you change direction at full speed. 10 reps.', 'Goal: reaction time under 0.3s. Track progress every 4 weeks — it''s a measurable skill.'] WHERE id = 'a1b1a2b4-fab4-44ee-b3dd-b0d9fa1dfc50';
UPDATE public.trainings SET title_en = 'Free Throw Ritual — Focus Routine', description_en = 'A pre-shot mental routine from the arsenal of Dirk Nowitzki, Ray Allen, and Steve Nash — all 90%+ from the line. The routine eliminates conscious thought and hands control over to motor habits. Start it today — it''ll stay with you for the rest of your career.', instructions_en = ARRAY['Pick a number of dribbles: 1, 2, or 3. Always the same number, always the same rhythm.', 'Look at the rim: find a specific point — the front hook, the middle of the hooks, the back of the rim. That''s your "target".', 'Breath: 1 deep breath before the first dribble, 1 calm one after setting the ball.', 'Mantra word (optional): one word, e.g. "up", "soft", "chute". Think it before you shoot.', 'Execution: identical leg tempo, identical ball path, identical landing.', 'Test the routine: 50 free throws with the full ceremony — each shot''s time should be in the 8–11s range.', 'Stabilize: 30 days of the same routine and you stop thinking — your body shoots on its own. That''s what you want.', 'In a game: when you''re at the line, the routine is your anchor. Even if you''re losing — come back to it.'] WHERE id = '98184693-786a-424f-8dd9-db9f290968c9';
UPDATE public.trainings SET title_en = 'Cone Dribbling — Slalom Agility', description_en = 'Slalom through cones — one of the most-used drills at the NBA Combine and in pre-draft workouts. Trains changing direction with the ball at full speed. Each cone is a defender you must beat without losing control.', instructions_en = ARRAY['Setup: 6–8 cones in a straight line, 1.5m apart. Start 3m before the first one.', 'Variant 1 — crossover at every cone: switch hands at each cone.', 'Variant 2 — between the legs: the ball goes under your leg at each cone.', 'Variant 3 — behind the back: a full behind-the-back move at each cone.', 'Variant 4 — spin move: a full body spin around each cone, ball protected.', 'Variant 5 — combo: 1 cross, 2 between, 3 behind back, 4 spin. Randomize the order.', 'Tempo: first pass slow (technique), second full speed. 5 passes per variant.', 'Time yourself — after a month of training it should drop by 15–20% with no loss of ball control.'] WHERE id = '29ca4b0c-c473-4859-a9c3-a080b0f1c089';
UPDATE public.trainings SET title_en = 'Threes — Fixed Spots', description_en = '"5 spots" — the classic NBA shooting-coach routine: 5 spots beyond the arc (2× corner, 2× wing, top of the key) × 10 shots = 50 threes from the full arc. Builds a repeatable motion at every angle of the floor.', instructions_en = ARRAY['Spots (starting from the right corner): corner R → wing R → top of the key → wing L → corner L.', 'Each spot: 10 catch & shoot attempts — a partner passes you the ball, or use a returner.', 'Clearing a spot: minimum 6/10 = move on. Less = repeat that spot.', 'Tempo: quick rhythm, don''t linger between shots — mimic a catch in game motion.', 'Feet: identical setup at all 5 spots — that''s the signal to your body "this is my shooting position".', 'After 50 shots, record the result per spot — wherever you''re weakest, do more reps there tomorrow.', 'Rotate direction: tomorrow start from the left corner — the reverse order requires adaptation.', 'Full session: 3 rounds of 50 shots = 150 attempts from distance. Real investment, real progress.'] WHERE id = '87f3fa5d-3977-41e7-b045-037423092b2a';
UPDATE public.trainings SET title_en = 'Catch & Shoot — Corner Three', description_en = 'Catch & shoot from the corner — the most common game-shot archetype at the NBA level: a shorter arc, a ready base, minimum time from catch to release. Klay Thompson, JJ Redick, Duncan Robinson — this is where the money is made.', instructions_en = ARRAY['Ready position: feet set before the catch, weight on the midfoot, hands in receiving position.', 'Catch fully squared up — no pivots or adjustments after receiving the ball.', 'Time from catch to release: 0.6–0.8s. Train the right tempo, without "thinking".', 'Partner: standing on the perimeter, throws a crisp chest-level pass (not overhead, not below the knee).', 'Without a partner: use a rebounder/returner, or bounce the ball off a wall from 2m.', 'Series: 30 passes from the right, 30 from the left. Goal = 18/30 (60%) each side.', 'Movement test: a partner passes with a delay or a close-out — learn to "shoot through pressure".', 'After the session, record the % from each side — corner R vs. L = a symmetry indicator of your shot.'] WHERE id = 'd36b230f-91ef-4787-8349-b114b6322687';
UPDATE public.trainings SET title_en = 'Off-the-Dribble Three', description_en = 'Off-the-dribble three created off your own move — the highest level of shotmaking. Curry, Lillard, Trae Young use it to open up spacing and punish switches. This is a shot you can''t "assist" — you create your own space and use it yourself.', instructions_en = ARRAY['Setup: half-court, ball in your hands from the top of the key.', 'Hesitation move or crossover: force the defender to react (you can practice with a cone).', 'Step-back: a step backward after the dribble creates separation.', 'Feet land behind the arc, not on it — control your landing spot consciously.', 'Release high, full extension — don''t sacrifice mechanics for speed.', 'Series: 5 step-backs R + 5 step-backs L + 5 side-steps R + 5 L = 20 attempts per set.', '3 sets = 60 attempts. Goal: 30% (NBA top creators shoot 35–40%).', 'With a partner: every crossover/hesitation finished with an aggressive close-out — game-speed intensity.'] WHERE id = '723cbda2-5400-42b8-8710-a0ff58350ceb';
UPDATE public.trainings SET title_en = 'Floater — The Scoop Shot', description_en = 'The floater (teardrop, runner) — a scorer''s tool against taller defenders. Tony Parker, Trae Young, Steph Curry built careers on this shot. High arc, soft mechanics, impossible to block by a 2m+ help defender.', instructions_en = ARRAY['Start: dribble in from half-court toward the rim.', 'Stopping point: 3–4m from the basket (between the free-throw line and the paint).', 'One-foot lift: jump off one leg (opposite your shooting hand) — like a layup, but without contacting the rim.', 'Release from a high-raised hand — elbow above the eyebrows, index finger pointing to the sky.', 'Arc: high, almost vertical — the ball drops onto the rim from above, not from the front.', 'Target: the center of the rim. Don''t use the backboard on a floater unless the angle is sharp.', 'Series: 10 floaters R + 10 L. Plus 10 "in motion" — after a sprint from 5m.', 'Goal: 50% makes. Remember — it''s a "soft" shot, minimal hand strength, maximum finesse.'] WHERE id = 'ffd83af0-3da4-45c5-afc0-5ba6f1fdc534';
UPDATE public.trainings SET title_en = 'Resistance Band Training', description_en = 'Band training — equipment used by every NBA performance specialist. Activates the hip and shoulder stabilizers that a barbell never loads. 20 minutes builds functional strength with zero injury risk.', instructions_en = ARRAY['Monster walks (band above the knees): 20 steps side-to-side each direction — glute medius.', 'Lateral band walks: 30 steps each direction, low stance — key for defense.', 'Glute bridges with a band: 3×15, knees pushing out against the resistance.', 'Banded pull-aparts: 3×15 — rear shoulder, prevents rotator cuff injuries.', 'External rotation (band against a wall): 2×12 each arm — rotator cuff.', 'Standing hip abduction: 2×15 each leg — hip stabilizer.', 'Banded clamshells: 3×15 each side — deep glute.', 'Cooldown: 2 minutes stretching the hips and shoulders.'] WHERE id = '7f801392-8b8a-44dc-8e3e-f95b547dd3bc';
UPDATE public.trainings SET title_en = 'Lower Body Explosion', description_en = 'Leg power is everything: jumping, sprinting, changing direction, fighting for position. Zion Williamson has the strongest legs in the NBA — squatting 800lbs at age 19. Your program: 6 compound exercises that build explosiveness, not just strength.', instructions_en = ARRAY['Goblet squat (squat holding a weight at chest): 4 sets × 12. Full depth — glutes below the knee.', 'Bulgarian split squat: 3 sets × 10 each leg. Back foot on a bench, front knee at 90°.', 'Romanian deadlift (RDL with dumbbells): 3 sets × 12. Stiff back, knees slightly bent, hips back.', 'Box jump (40–50cm box): 4 sets × 5. Explosive up, controlled step-down (better to step down than jump off).', 'Walking lunges with dumbbells: 3 sets × 10 each leg. Step forward, knee touches the floor.', 'Calf raises: 3 sets × 20. Stand on a step, full range of motion, control in both directions.', 'Finish: 5 minutes of foam rolling quads + hamstrings + calves.', 'Frequency: 2x a week, always with a 48-hour gap. Don''t do this before shooting or plyometrics on the same day.'] WHERE id = 'c241f602-0001-49d4-830f-891bfdc71eda';
UPDATE public.trainings SET title_en = 'Upper Body Strength', description_en = 'Arm, shoulder, and chest strength translates directly into shooting power, contact tolerance, and battles for position. Every NBA player has 2 upper-body sessions a week. Heat preseason standard: 3 times a week, 45 minutes each.', instructions_en = ARRAY['Standard push-ups: 4 sets × as many as you can (goal: 30+ per set). Full range, chest touches the floor.', 'Pull-ups (overhand grip): 3 sets × max. If too few — use a resistance band for assistance.', 'Dumbbell press (lying down): 4 sets × 10. Full range, controlled lowering phase.', 'Bent-over row (barbell or dumbbells): 4 sets × 10. Neutral spine, shoulder blades pulled together.', 'Overhead press (dumbbells): 3 sets × 10. Standing, core tight, no back arching.', 'Lateral raises (dumbbells out to the side): 3 sets × 12. Elbow slightly bent, to shoulder height.', 'Bicep curls + tricep extensions (superset): 3 sets × 12 each move. Light control, no swinging.', 'Frequency: twice a week. After the session: 5 minutes foam rolling the chest, shoulder blades, and shoulders.'] WHERE id = 'cbd4dde1-c5e1-467d-927d-ef3690461661';
UPDATE public.trainings SET title_en = 'One-Hand Ball Control', description_en = 'Single-hand micro-control — the art of "talking to the ball" you see in Kyrie Irving. You work purely on feel, not movement. This is where your entire dribbling handle is built: before your hands can react in motion, they need to know what to do standing still.', instructions_en = ARRAY['One-hand pound dribble: 100 hard bounces R, 100 L. Ball height = waist.', 'Side dribble (at the hip): 50 reps R, 50 L. Ball in line with your hip.', 'Front-to-back: the ball travels front to back under your foot. 30 R, 30 L.', 'Figure-8 around one leg: 20 R, 20 L. Foot still, ball draws a figure 8.', 'V-dribble on a diagonal: 30 reps each hand, the ball cuts at a 45° angle.', 'High-low: 20 high (head) + 20 low (knee) bounces each hand.', 'Wall taps: standing next to a wall, the ball bounces off it — 30s each hand, as fast as possible.', 'Goal: the ball leaves your hand and comes back on its own. Your hand doesn''t think — it feels.'] WHERE id = '5e24da7a-998d-4ab3-82f8-4a540faf0d5b';
UPDATE public.trainings SET title_en = 'Weak Hand Challenge — Left Only', description_en = '15 minutes without your right hand. LeBron James spent all of summer 2008 touching the ball only with his left — the result: an improved handle visible from the season''s very first game. Defenders know which hand you protect. Time to surprise them.', instructions_en = ARRAY['Rule: for 15 minutes your right hand does NOT touch the ball. It drops — you pick it up with your left.', 'Stationary pound L: 100 hard bounces, low ball, controlled mechanics.', 'Crossover L→R and back to L (passing through the right only as a "tap"): 50 reps.', 'Between the legs with L only: 30 reps, hip rotates.', 'Behind the back L: 30 reps, the arm leads.', 'Layups with the left only: 20 from the left side of the rim, 10 from the right (reverse layup).', 'Bonus: one day a week, eat with your left hand. Write with your left. Open doors with your left.', 'Goal after 30 days: left = 80% of right''s strength. After 6 months: no difference.'] WHERE id = '7f86b650-560b-4086-b498-04fc59d1d7be';
UPDATE public.trainings SET title_en = 'Dribbling in Motion — Full Court', description_en = 'Ball control at game speed, not standing still. Every length of the court calls for a different technique. Stationary work gives you the foundation, but the game happens at a sprint with your head up — seeing the court, reading the defense, dribbling without looking.', instructions_en = ARRAY['Length 1–2: speed dribble right going, left coming back — sprint, ball high at your hip.', 'Length 3–4: crossover every 5m — switch hands at marked points (court lines).', 'Length 5–6: between the legs every 5m — at full speed, no stopping.', 'Length 7–8: behind the back every 5m — hip rotation, ball behind your back.', 'Length 9–10: in and out + crossover in one rhythm. Simulates dribbling past a defender.', 'Length 11–12: spin move — a full spin with the ball, 2× per length of the court.', 'Length 13–14: hesitation every 5m + a quick burst. "Stop-go-stop-go".', 'Length 15–20: any moves you like, but head up — look at the ceiling, not the ball.'] WHERE id = 'e1e5cef4-be10-424f-bc81-6383ef1c1466';
UPDATE public.trainings SET title_en = 'Vertical Jump Training', description_en = 'A plyometric jumping protocol — the same one NBA trainers use to build verticality in young players. Zion measured a 45-inch vertical. Every centimeter is the difference between a blocked shot and a finished assist.', instructions_en = ARRAY['10-min warmup: jog + dynamic stretches + 5 jumps at full amplitude.', 'Box jump (40–60cm box): 4 sets × 5 reps. Focus on explosion, not height — controlled descent.', 'Depth jump (step off the box + immediate jump up): 3 sets × 5. A minimal ground pause is critical.', 'Single-leg bound (single-leg jump with full extension): 3 sets × 6 each leg.', 'Tuck jump (knee-to-chest jump): 3 sets × 8 reps.', 'Safety: finish every jump with a controlled landing (a quiet floor = good technique).', 'Frequency: max twice a week, always with a 48-hour gap between sessions.', 'Measure your vertical every 4 weeks — against a wall, mark + jump touch. Average progress: 1cm/month over 6 months.'] WHERE id = 'f0b89fef-c835-42ba-8585-5aee465e0323';
UPDATE public.trainings SET title_en = 'Ballhandling — Iso Moves Series', description_en = 'Iso moves — your "signature series" of 5–6 moves you drill thousands of times. Every elite NBA scorer has one: Curry — between the legs + step-back, Kyrie — double crossover, Harden — euro step. Time to build yours.', instructions_en = ARRAY['Pick a package of 5 moves — start with: hesitation, crossover, between-the-legs, behind-the-back, step-back.', 'First set — each move + drive to the rim: 10 reps per move (50 total).', 'Second set — each move + pull-up jumper: 10 reps per move (50 total).', 'Third set — each move + step-back three: 10 reps per move (50 total).', 'Fourth set — random generator: a partner shouts a move + finisher. 30 reps.', 'Every move from both the right and left side — symmetry is mandatory.', 'After 6 months: add 2 advanced moves (double crossover, snatch back, in-out cross).', 'Tip: your 5 moves = 5 ways to ALWAYS score. No compromises.'] WHERE id = '46313ac3-2689-4328-9899-e977aa7a0539';
UPDATE public.trainings SET title_en = 'Pressure Dribbling — Defender in Your Face', description_en = 'Training under defensive pressure — the final test of your handle. Without it, stationary and full-court work are just theory. A partner actively disrupts you, and you have to keep the ball and find a way out. It''s the only way to reach game-speed level.', instructions_en = ARRAY['With a partner (option A): the partner stands 1m in front of you, actively poking at the ball. Your job — keep dribbling for 60s without losing it.', 'With a partner (option B): the partner simulates a defender, you try to break their line 5 times in 60s.', 'Without a partner (option A): 1–2kg wrist weights — make every move harder.', 'Without a partner (option B): practice against a wall — the ball bounces off the floor and the wall, control the direction.', 'Without a partner (option C): dribble with your eyes closed — 30s, force your brain to rely on feel.', 'Advanced variant: two balls + wrist weights, 30s.', 'Full series: 5 rounds of 60s work + 30s rest = 7.5 minutes of total stress.', 'After the session: record how many times you lost the ball. Goal — cut it by 1 every week.'] WHERE id = '617e63a9-b2be-4c29-b9b3-9255a2fcb36f';
UPDATE public.trainings SET title_en = '17s — NBA Conditioning Test', description_en = 'The official conditioning test from NBA preseason camp. 17 full lengths of the court (94 feet each) within 60 seconds, with a 25s active rest. Used by Steve Kerr at the Warriors, Spoelstra at the Heat, Rivers at the Sixers. The first 10 reps are the start — the last 7 are character.', instructions_en = ARRAY['10-min warmup: jog + dynamic stretches + 3 progressive sprints (50%, 75%, 90%).', 'The test: 17 lengths of the court (each 28m) in 60 seconds — that''s ~3.5s/length.', 'After every completed 17 — 25 seconds of active rest (walking, not sitting).', 'Repeat 4 times. Each round should fit within 60s — if you go over, the round doesn''t count.', 'Time it precisely — a stopwatch or an app. Any drop in pace is a "DNF" for that round.', 'Goal for competitive level: 4 rounds within time. NBA level: 5 rounds.', '10-min cooldown: easy jog + static stretching.', 'Run the test once every 2–3 weeks — track progress. Prep training: suicides and full-court intervals.'] WHERE id = 'ac83f6a2-0e2a-4c79-9b5c-6321d2a70861';
UPDATE public.trainings SET title_en = 'Suicide Sprints', description_en = 'A classic from the NBA Draft Combine — the truth test for every player. Sprint to each line of the court and back, in growing distances. The same fatigue as the 4th quarter of a playoff game. The same mental toughness required: to finish.', instructions_en = ARRAY['Start: low stance, one foot behind the baseline, weight on the midfoot.', 'Sprint to the free-throw line (5.8m) → touch the floor → sprint back to the start.', 'Sprint to the half-court line (14m) → touch → sprint back.', 'Sprint to the far free-throw line (22m) → touch → sprint back.', 'Sprint to the far baseline (28m) → touch → sprint back. That''s one set.', 'Rest 60–90 seconds between sets (active walking).', 'Complete 10 sets. Time each one — the difference between the 1st and the 10th shouldn''t exceed 5 seconds.', 'NBA Combine standard: a full set in 30 seconds. Competitive standard: 35 seconds.'] WHERE id = '505fe119-f983-4725-99a1-d3432cfc27ae';
UPDATE public.trainings SET title_en = 'Explosive First Step', description_en = 'The first step decides whether the defender has time to react. Westbrook, Wall, Rose — all had a first step so fast the defender hadn''t even started moving yet. Training the explosiveness of those first 30cm — the difference between a layup and a turnover.', instructions_en = ARRAY['Warmup: 5 minutes of jogging + 3 progressive 10m sprints (50%, 75%, 100%).', 'Reactive start drill: stand in your stance, wait for the signal (clap/whistle), explode 5m at max.', 'Do 10 reps from the right side, 10 from the left. Full rest between (45s).', 'Single-step lateral drive: low stance, one explosive step sideways, stop, return. 15 R, 15 L.', 'Punch-out drill: fake a crossover, explode the other direction off your other foot. 10 R, 10 L.', 'With equipment: use a cone — explode one way, cross, explode the other. 8 reps.', 'Test: measure your first-step distance — from your start mark to your first landing mark. Goal: 1m+.', 'Tip: the first step always comes from a loaded stance, knees bent. Without the load — no power.'] WHERE id = '628e98c5-d0c6-440c-9b78-8a304f89fedc';
UPDATE public.trainings SET title_en = 'Jump Rope — NBA Style', description_en = 'The jump rope — a conditioning secret of many NBA greats. Kobe Bryant started every session with 10 minutes of it. Mike Tyson used it as his main cardio. Builds foot coordination, cardiovascular fitness, and calf strength simultaneously — in 1/3 of the time vs. running.', instructions_en = ARRAY['Gear: a rope with a plastic cord (not a thick rope — too slow). Length = handles reach your armpits when you stand on the middle of the rope.', 'Stance: arms at your sides, elbows close to your body, your wrists spin the rope — not your shoulders.', 'Basic jump (both feet together): 100 reps, low jumps (5cm), soft landing on the midfoot.', 'Alternating foot (like running): 100 reps, knees up.', 'High knee: 50 reps, knees to hip height, intense.', 'Double under (rope passes twice per jump): 20 reps (advanced).', 'Boxer skip (1-2 step): 60 seconds of continuous movement.', 'Session goal: 300 jumps without losing rhythm. Time: 5–7 minutes. Train 5 minutes daily instead of 30 minutes once a week.'] WHERE id = '2ba19883-98a5-4535-b279-58317c3bf5c7';
UPDATE public.trainings SET title_en = 'Free Throws — Series of 100', description_en = 'Free throw fundamentals — the only situation in the game where you have full control: no defender, no movement. Curry hits 91% of his free throws off hundreds of thousands of reps. It''s not talent — it''s repeatable mechanics and an unchanging routine.', instructions_en = ARRAY['Stand at the line: feet in a fixed position (shooting foot slightly forward), toe on the center mark of the line.', 'Catch the ball, run your routine — 2 dribbles + ball spin + a breath. ALWAYS the same.', 'Set position: ball at the "shot pocket" (chin height, slightly toward your shooting hand).', 'Shot: full extension of knees + hips + arm, finishing on your toes with a relaxed wrist.', 'Series: 10 shots in a row × 10 rounds = 100 free throws. A short rest between rounds.', 'Track your makes per round. Goal = 8/10 minimum, 9/10 = competitive level.', 'If you hit fewer than 5/10 — take 5 extra from a half-position next to the basket, then return to the line.', 'After 100, record your overall percentage. Track it weekly — it''s your "shooter identity".'] WHERE id = 'f3c5e020-7836-4c60-b5fc-0446cd1b1625';
UPDATE public.trainings SET title_en = 'Pull-Up Jumper — Off the Dribble', description_en = 'The pull-up midrange is the test of a true scorer. Lillard, Mitchell, Harden, and Booker use it in key moments when the defender drops under the screen. It requires perfect timing between your legs, hips, and arm right after the dribble.', instructions_en = ARRAY['Start: ball in motion (1–2 dribbles) from half-court toward the rim.', 'Hesitation or regular rhythm: the second dribble is the "gather" — preparing your legs to jump.', 'Jump stop (1-2 step or one-two): feet parallel under your weight, low stance.', 'Pull-up: jump vertically, not forward. Shoot from the highest point of your jump.', 'Hand mechanics identical to a spot-up shot — controlled landing with full follow-through.', 'Series: 10× from the right, 10× from the left. 60 attempts total (3 rounds).', 'Goal: 40–45% makes. That''s elite NBA level.', 'Pressure test: a partner simulates a close-out — learn to release quickly off the move.'] WHERE id = 'e69a1574-cb56-47f5-8c76-dc51b2c55429';
UPDATE public.trainings SET title_en = 'Midrange — Post-Up and Fadeaway', description_en = 'Post-up + fadeaway from the arsenal of Kobe Bryant and Kevin Durant. An element of the game "lost" in the three-point era, but making a comeback with Embiid and KD today. Backing down the defender, spinning, and shooting with a lean — impossible to block once the mechanics are dialed in.', instructions_en = ARRAY['Starting position: 3–4m from the basket, back to the rim, in a low post stance.', 'A partner simulates the defender — leaning on your back, you hold the contact.', 'Drop step: one foot behind the defender, opening the hip toward the basket.', 'Pivot on your back foot, rotate through your strong side — ball high, protected.', 'Fadeaway: jump vertically + a slight lean away from the defender (5–10°). No more — you''ll wreck the mechanics.', 'Release at the peak of your jump, long follow-through (fingers pointing at the rim).', 'Series: 10 attempts from the right block, 10 from the left, both spin directions = 40 shots.', 'Goal: 50%+ from the post midrange. That''s efficient post-scorer level.'] WHERE id = '17b32dc5-e1c8-4716-b5e0-e9f0ae909e25';
UPDATE public.trainings SET title_en = 'Grip & Wrist Strength', description_en = 'Grip and wrist strength directly affects ball control, shooting power, fighting for rebounds, and steals. LeBron James has a grip stronger than an average MMA strangler — because he knows the first person who lets go of the ball in a battle for it loses possession.', instructions_en = ARRAY['Hang from a bar: 3 sets × as long as possible. Goal: 60+ seconds per set. The base test.', 'Farmer carry (walking with heavy dumbbells): 3 sets × 30 meters. Weight = 50% of body weight per hand.', 'Plate pinch (pinching a plate with your fingers): 3 sets × 30s. Two small plates (1.25kg or 2.5kg) held with fingers only.', 'Dumbbell wrist curls: 3 sets × 15 each arm. Forearm on a bench, full wrist range of motion.', 'Reverse wrist curls: 3 sets × 12 each arm (forearm down, wrist extends the opposite way).', 'Rice bucket exercises: bury your hand in rice, open/close your fingers for 30 seconds. Great for small muscles.', 'Ball squeeze: squeeze a rubber ball — 50 reps each hand. Do it during rest periods.', 'Test: bend the bar (a light steel rod) — if you can''t bend a 6mm rod, your grip is weak.'] WHERE id = '5fa93238-2bb6-4b77-a99b-6ff1fcffc330';
UPDATE public.trainings SET title_en = 'Basic Dribbling — 5 Moves', description_en = 'The "Big Five" — a fundamental set used by Magic, Stockton, and Chris Paul for decades. Five moves you need in your arsenal before anything advanced will work. 10 minutes daily for a year = your hands react on their own.', instructions_en = ARRAY['Crossover (R↔L in place): 40 reps, low ball, weight shifts smoothly.', 'Between the legs: 40 reps. Opposite foot is forward, the ball cuts under it.', 'Behind the back: 40 reps. Hip opens, the hand guides the ball behind your back.', 'In and out (fake-cross): 40 reps each hand. The ball goes inward, comes back — without switching hands.', 'Hesitation (stopping the dribble): 40 reps. 1s pause + a quick burst. Mimic freezing the defender.', 'Do each move in 2 rounds: 1× slow (clean mechanics), 1× full speed.', 'Goal: the whole session in 10 minutes. Every day for 30 days — your first level of mastery.', 'Test: record yourself from the side — zero visual contact with the ball for the entire 10 minutes.'] WHERE id = 'b48c52c8-4247-4012-a52f-596d6a820391';
UPDATE public.trainings SET title_en = 'Core Stability — Center of Gravity', description_en = 'A strong core is the foundation of everything: balance through contact, stability on your shot, strength in the fight under the basket. Every NBA player has 30+ minutes of core work in their weekly plan. It''s not a six-pack — it''s your "anchor" for generating power from your hips.', instructions_en = ARRAY['Standard plank: 3 sets × 60 seconds. A straight line from shoulder to heel, no sagging at the hips.', 'Side plank: 2 sets × 45 seconds each side. Elbow under the shoulder, hips lifted.', 'Dead bug: 3 sets × 12 reps. Lying on your back, opposite arm and leg extend, back stays flat on the floor.', 'Bird dog: 3 sets × 10 each side. On all fours, opposite arm and leg, control your balance.', 'Russian twists: 3 sets × 30 reps (with a 4kg ball or without). Torso to 45°, touch the floor on both sides.', 'Hollow body hold: 3 sets × 30 seconds. Flat back, legs and arms a few cm off the floor.', 'Pallof press (with a band): 3 sets × 10 each side. Hold the resistance at your side, press it forward.', 'Finish: 60 seconds of deep breathing lying down — activates your diaphragm, a key core element.'] WHERE id = '2736cfda-95bf-4f5d-8dd9-777a4d10c4b0';
UPDATE public.trainings SET title_en = 'Ice Massage — Ice Bath or Ice Pack', description_en = 'Cold therapy right after training lowers inflammation in your muscles, reduces micro-damage, and significantly speeds up recovery. A standard in NBA recovery rooms — from the Lakers'' ice tubs to portable coolers on team buses.', instructions_en = ARRAY['Ideally: an ice bath at 10–12°C, submerged to the waist, for 5–10 minutes.', 'No tub: gel packs / an ice bag wrapped in a towel.', 'Apply the pack for 15–20 minutes to the biggest areas — knees, ankles, lower back.', 'Max 20 minutes per spot, then 30 minutes of rest.', 'Breathe calmly through your nose — the cold shock triggers panic for the first 30s, then it passes.', 'Never put ice directly on skin — always through a towel or clothing.', 'After finishing: a warm contrast shower (3 min warm / 30s cold × 3).'] WHERE id = '8f2b0208-859f-4cd9-b50c-a1e208f8cad9';
UPDATE public.trainings SET title_en = 'Dynamic Stretching — Morning Ritual', description_en = 'Dynamic stretching — the standard pre-game warmup for every NBA team. Unlike static stretching: it activates muscles, raises body temperature, increases joint range of motion, and prepares your nervous system. Essential before every main session.', instructions_en = ARRAY['Leg swings (front-to-back): 15 reps each leg, hold a wall for balance.', 'Lateral leg swings (cross-body): 15 reps each leg.', 'Walking lunges with rotation: 10 reps each side. Step into a lunge + rotate the torso toward the front leg.', 'High knee marching: 20 steps, knee to hip, arms work opposite.', 'Butt kicks (heels to glutes): 20 steps, fast tempo.', 'Carioca (lateral crossover walk): 20 meters each side. Activates the hips, improves coordination.', 'Arm circles: 15 forward + 15 backward, each arm at full range.', 'Inchworm: 8 reps. From standing, touch your hands to the floor, "walk" your hands out to a plank, return.'] WHERE id = 'cb4d5efc-21fc-481d-8447-eb76b0937ad8';
UPDATE public.trainings SET title_en = 'Meditation & Focus — 10 Minutes', description_en = 'Phil Jackson-style mindfulness — a protocol from the Bulls and Lakers era. 10 minutes a day lowers cortisol, raises focus by ~14% (UCLA study), and teaches mental quiet in the key moments of a game.', instructions_en = ARRAY['Sit upright, eyes closed or a soft gaze 1m ahead.', 'First 2 minutes: just observe your breath, don''t change it.', 'Next 5 minutes: count breaths to 10, then start over. When thoughts pull you away — return to "1".', 'Last 3 minutes: visualize one specific moment from today''s training — a shot, a dribble, a decision.', 'Don''t fight your thoughts — let them flow by, like clouds.', 'To finish: 3 deep breaths, open your eyes slowly, stand up calmly.'] WHERE id = '8a61687e-a9dd-4b14-96a2-93525d746494';
UPDATE public.trainings SET title_en = 'Foam Rolling — Muscle Release', description_en = 'A standard foam rolling protocol from NBA recovery rooms — breaks up the fascial trigger points that form after a high-intensity session. 10–15 minutes post-training = faster recovery, less soreness tomorrow.', instructions_en = ARRAY['Time: 10–15 minutes total, 60–90s per muscle group.', 'Tempo: very slow, 2–3 cm per second. Fast rolling doesn''t work.', 'Calves: roller under the calf, other leg on top for extra weight, 60s each leg.', 'IT band (outer thigh): side position, hold the most painful spot for 30s.', 'Quads: lying on your stomach, roller under the thigh, 60s each leg.', 'Glutes: sit on the roller, one leg crossed over, 60s each side.', 'Upper back: roller across your shoulder blades, arms crossed over your chest, 60s.', 'When you find a painful spot — stop, take 5 deep breaths, the muscle will release.'] WHERE id = '93343720-fc0c-4752-916d-dc1a984c1530';
UPDATE public.trainings SET title_en = 'Sports Nutrition — Meal Prep', description_en = 'A nutrition protocol from NBA dietitian methodology. An athlete burning 3000–4000 kcal a day without planned meals runs a deficit: energy, recovery, and focus all drop. Meal prepping once a week = 7 days of stable fuel.', instructions_en = ARRAY['Plan 5 meals a day: 3 main + 2 snacks (pre/post training).', 'Every main meal: protein (chicken/beef/fish) + complex carbs (rice/grains/potato) + vegetables.', 'Pre-workout (90 min before): a banana + 30g of nuts + a glass of water.', 'Post-workout (15 min after): 30g of whey protein + simple carbs (banana/fruit/honey).', 'Hydration: minimum 3L of water daily, 4L on training days. Add salt consciously.', 'Do it once: cook 1kg of rice, 1kg of chicken, chop vegetables — 7 lunchboxes ready in an hour.', 'Eliminate: added sugar, alcohol, fried food — not "completely", but save them for special occasions.'] WHERE id = '49cf5b07-5725-4e41-91e5-fb7c0b6d9cdc';
UPDATE public.trainings SET title_en = 'Cold Shower — Cold Exposure', description_en = 'A cold exposure protocol from the Wim Hof method, used by LeBron, Ja Morant, and most NBA performance teams. Cold water lowers post-training inflammation and builds mental toughness — the same tolerance for discomfort you''ll use in the 4th quarter.', instructions_en = ARRAY['First, a normal shower — wash with warm water.', 'Gradual cooldown: the last 60–90 seconds with cold water only (10–15°C).', 'Start with your feet and legs — the least shocking, gives you time to adapt.', 'Then your back, chest, hands. Face last.', 'Breathe calmly through your nose — inhale 4s, exhale 6s. Don''t hyperventilate.', 'The first 20–30s your brain screams "get out". Push through — then your body adapts.', 'Step out, dry off briskly with a towel — blood rushes back, you feel a euphoric rush (norepinephrine).', 'Do it daily. Even 30s is enough for the effect. Build up gradually to 2–3 minutes.'] WHERE id = 'f70c7802-9985-4715-baeb-f46100a4382d';
UPDATE public.trainings SET title_en = 'Film Study — Watch NBA the Smart Way', description_en = 'Film study at the level of an NBA assistant coach. 30 minutes of focused analysis of a player at your position gives you more than 2 hours of SportCenter highlights. Jason Kidd watched 4 hours a day — he was beating defenders before his first dribble.', instructions_en = ARRAY['Pick 1 player at your position with a profile you want to develop (not your "favorite" — a model to learn from).', 'Put the game on, but watch ONLY him — regardless of where the ball is.', 'Observe: footwork off the ball, body angle on defense, screen reads, decisions made 0.5s before receiving the ball.', 'Pause the video every 5 minutes and describe in one sentence what you just saw.', 'At the end, pick 1 concrete takeaway — e.g. "step-through finish right after a crossover". Try it tomorrow at training.', 'Time: 30 minutes of analysis is enough. Don''t jump between clips, watch it through.'] WHERE id = '68f2db46-4100-42c5-997f-0169779af829';
UPDATE public.trainings SET title_en = 'Sleep & Evening Routine', description_en = 'A sleep protocol based on Matthew Walker''s research (Why We Sleep) and NBA Sports Science data. LeBron sleeps 10–12h, Federer 12h, Curry 9h. Sleep deprivation lowers reaction time by 11% — that''s the difference between a shot on defense and a foul.', instructions_en = ARRAY['A fixed bedtime and wake-up time — weekend/weekday difference no more than 30 minutes.', '2h before bed: no screens, or block blue light (glasses/night mode).', '1h before bed: light stretching/yoga or reading a paper book, not social media.', 'Bedroom: 17–19°C, maximum darkness, no electronics in sight.', 'No caffeine after 2pm — its half-life is 6h, it lasts longer than you feel.', 'Last meal at least 3h before bed — a full stomach disrupts REM phases.', 'Goal: 8h of actual sleep (not time in bed). On training days, aim for 9h.', 'If you can''t fall asleep within 20 minutes — get up, do 10 minutes of a calm activity, then go back.'] WHERE id = '5a10970e-7cf7-43e0-a2cd-bc60a7b693ab';
UPDATE public.trainings SET title_en = 'Two-Ball Dribbling — Both Hands at Once', description_en = 'Two balls at the same time — the fastest way to even out your hand strength. A standard for young players at Bulls and Lakers academies. Your weaker hand has to keep up, because when it doesn''t, the ball drops. Zero compromise.', instructions_en = ARRAY['Gear: two balls of the same size and pressure.', 'Equal pound (both bounces together): 50 reps, metronome rhythm. Builds synchronization.', 'Alternating (R goes down, L goes up): 50 reps. Harder — alternating rhythm.', 'High-low (one ball higher, one lower): 30 reps in each variant (R high / L high).', 'Crossover with two balls: 30 reps. The balls cross in front of your torso at the same moment.', 'V-dribble with two: 30 reps. Hard — requires 100% control of both hands.', 'Walking two-ball: 1 length of the court under control, balls in even rhythm.', 'If a ball drops — pick it up immediately and continue. Frustration is part of the process.'] WHERE id = 'd44257c7-961d-4219-a2b0-d9d400866fa3';
UPDATE public.trainings SET title_en = 'Morning Wake-Up — Flow Movement', description_en = 'A ten-minute morning mobility protocol used by team trainers to wake up the nervous system after sleep. Lubricates the joints and activates the fascia — without it, your first quarter is a lottery.', instructions_en = ARRAY['Neck circles: 5 slow ones each direction, breathe through your nose.', 'Shoulder circles: 10 forward, 10 backward, arms loose.', 'Torso twists: 10 reps, feel your obliques working.', 'Hip circles (hula-hoop): 10 each direction — a wide range.', 'Leg swings front-to-back: 10 reps each leg, hold a wall for balance.', 'Leg swings sideways (cross-body): 10 reps each leg.', 'World''s Greatest Stretch: 5 reps each side — lunge + rotate + touch the floor.', 'Finish with 5 deep breaths standing — ready for the day.'] WHERE id = '2c41db22-5ee7-4648-91a3-b5e738d892d6';
UPDATE public.trainings SET title_en = 'Warmup With the Ball', description_en = 'A standard warmup before the main session with the ball in your hands — combines activating your nervous system with building ball feel. Every NBA practice starts with a similar protocol.', instructions_en = ARRAY['Marching dribble across the whole court: right hand there, left hand back (×2 lengths).', 'Figure-8 between your legs standing still: 30 seconds, control the ball height.', 'Two-hand pound dribble in place: 15 hard bounces each hand.', 'Wall taps: stand by a wall, one-hand dribble high (forehead level) — 30s each hand.', 'Crossover in place (low/wide stance): 30 reps.', 'Dribble sprint to half-court + jump stop + pivot: 3 times.', 'A light shot from 3m off the backboard: 10 times, clean mechanics, no forcing.'] WHERE id = 'ba4345f4-8838-4046-8d0b-11bf27a7aea9';
UPDATE public.trainings SET title_en = 'Free Throws Under Pressure — After Cardio', description_en = 'Simulating in-game fatigue — the crucial free throws come at the end of a quarter, when your heart is pounding at 170 bpm. Curry, Kawhi, and Damian Lillard finish their sessions with free throw series only after cardio. Only this kind of training reflects real pressure.', instructions_en = ARRAY['Full court sprint there and back × 4 — fast at the very end, the last length at max.', 'Right after the sprint, go straight to the line, start your routine. No rest.', 'Shoot 10 free throws. Measure: makes + time for the whole series.', 'Repeat the cycle 5 times = 50 free throws under cardio.', 'Benchmark: 7/10 while fatigued = NBA-ready, 8/10 = future All-Star.', 'Breathing: don''t try to calm down — run the routine with heavy breathing, just like in a game.', 'Mentally: every round = the last minute of the game, a tied score.', 'After the session: log your daily percentages, track the weekly trend — that''s your clutch index.'] WHERE id = '6d4e914a-7124-43ee-ae81-d110b3d47d2a';
UPDATE public.trainings SET title_en = 'Bank Shot From the Side', description_en = 'A bank shot from a 45° angle — the highest-percentage shot in the entire midrange arsenal. Tim Duncan built a career and 5 championships on the bank shot. The backboard forgives more than the rim — from the right angle, it''s your biggest ally.', instructions_en = ARRAY['Position: 3–5m from the basket, exactly at a 45° angle (one foot behind the extension of the backboard line).', 'Target on the backboard: the top corner of the white square on your side. Aim there, not at the rim.', 'Shooting mechanics identical to a normal jumpshot — only the target point differs.', 'Trajectory: the ball bounces off the square and drops straight into the rim, without touching the rim''s edge.', 'Series: 20 from the right × 20 from the left, 5 from each of 4 spots (close/mid/long/short corner).', 'Goal: 70% makes from a good angle — that''s better than the league''s midrange average.', 'Test: add contact — introduce a move before the shot (a jab step or test-step) — maintain 60%.', 'Tip: the ball MUST hit the backboard at a 90° angle to the floor — too flat and it''ll bounce sideways.'] WHERE id = '29ee9d75-5d34-4b28-92c5-48dcaf92c34f';
UPDATE public.trainings SET title_en = 'Single-Leg Strength', description_en = 'Strength asymmetry between legs is the most common cause of injury in basketball players — 7 out of 10 ACL tears originate in the weaker leg. Kevin Durant treats single-leg work as a mandatory part of his protocol. It''s not an "extra" — it''s the foundation of longevity.', instructions_en = ARRAY['Pistol squat (single-leg squat): 3 sets × 5–8 each leg. You can hold a wall for balance at first.', 'Single-leg RDL (single-leg deadlift): 3 sets × 10 each side. Touch the floor with your hand, the other leg stays in line with your torso.', 'Step-up onto a box (45cm): 3 sets × 12 each leg. Full stand on one leg, controlled descent.', 'Single-leg glute bridge: 3 sets × 15 each leg. Other leg raised, hips up.', 'Bulgarian split squat with dumbbells: 3 sets × 10 each side. Increase the load progressively.', 'Single-leg calf raise: 3 sets × 15 each leg. Full range on a step.', 'Asymmetry test: compare rep counts R vs L in the pistol squat. A difference > 20% = a serious issue.', 'After the session: 10 minutes of foam rolling quads, IT band, calves — the deepest recovery work.'] WHERE id = 'e91573d0-6a57-4984-a620-5db0f6f934b0';
UPDATE public.trainings SET title_en = 'Hesitation Dribble — The Fake Step', description_en = 'Hesitation — "freezing the defender". James Harden uses it 15–20 times a game: a stop-step + explosion, creating a 0.3s gap where the defender is flat-footed. That''s enough to drive by or get off a clean shot.', instructions_en = ARRAY['Start: dribbling at full speed toward the defender/cone.', 'Hesitation step: your right leg "fakes" stopping — full weight, knee bent.', 'The ball slows down at the same time (a 0.3–0.5s pause) — the defender thinks you''re stopping.', 'Acceleration: a second step explodes forward, the ball continues in the same direction.', 'Variant 1 — hesi + drive: after stopping, you drive the same direction. 20 reps R, 20 L.', 'Variant 2 — hesi + crossover: after stopping, you change direction. 20 R, 20 L.', 'Variant 3 — hesi + pull-up: the stop becomes a real shot. 20 reps.', 'Test: record yourself — your shoulders and head during the hesitation must look identical to a real stop, or the defender won''t bite.'] WHERE id = '637e5a55-6951-4c67-9904-b3619f0a2eb0';
UPDATE public.trainings SET title_en = 'Pull-Up Three Off the Dribble', description_en = 'The pull-up three — one of the hardest shots in a game arsenal. Damian Lillard and Trae Young build their entire offensive plan around it: a three after 1–2 dribbles from distance that the defender can''t react to. Requires explosive hips and full balance control.', instructions_en = ARRAY['Start: position beyond the arc, ball in your hands with an upright posture — ready stance.', '1–2 controlled dribbles: the first is a pull, the second is the "gather" under your legs.', 'Jump stop under your weight — feet slightly behind the arc, since the jump will push you toward the middle of the court.', 'Full vertical jump: knees-hips-arms in one kinetic line.', 'Release at the peak of the jump, NOT while fading — stay over the ball through the follow-through.', 'Series: 20 attempts from each of 3 spots (top, R wing, L wing) = 60 shots.', 'Goal: 30% makes. That''s competitive-level scorer benchmark.', 'Tip: keep your balance — the most common mistake is jumping backward, which kills your range.'] WHERE id = '69849d98-e6e8-4c0b-bf30-60883a3fa9f9';
UPDATE public.trainings SET title_en = 'Off-Screen Shooting', description_en = 'A shot off coming out of a screen — one of the 3 most common scenarios in an NBA playbook. Klay Thompson, Bogdan Bogdanović, Buddy Hield make their living entirely off this move: ready before the catch, balanced in the sprint, release in 0.5s.', instructions_en = ARRAY['Setup: a partner holds the ball for a pass from the top of the key. A cone/chair simulates the screen.', 'Run at full speed toward the screen — not a jog, a real game-speed sprint.', 'Tight curl: go as close as possible to the "screen" — your elbow brushes the cone.', 'Inside foot pivot: the inside foot lands first, the other follows squared up.', 'Catch fully squared up — no adjustments after receiving. Hands ready before the catch.', 'Release within 0.6–0.8s of the catch. Tempo, not a relaxed rhythm.', 'Series: 10 from the right, 10 from the left, each with 3 variants (curl, flare, fade) = 60 shots.', 'Goal: 50% makes on catch & shoot off a screen. That''s "Klay Thompson tier" benchmark.'] WHERE id = '76c1c020-9962-4edd-9082-40f557c3eda1';
UPDATE public.trainings SET title_en = 'Stationary Dribbling — Hand Isolation', description_en = 'The foundation of every ballhandler. Kyrie Irving spent 4 years working only on stationary dribbling before stepping onto the court with elite-tier moves. Builds the neuromuscular connection between hand and ball before you move into motion.', instructions_en = ARRAY['Stance: low, knees bent, back straight, weight on the midfoot.', 'Pound dribble right hand: 100 hard bounces using only your fingers, ball NEVER above waist height.', 'Pound dribble left hand: 100 hard bounces. Goal — no strength difference between hands.', 'Crossover in place (low/wide stance): 50 reps, the ball cuts under your knees.', 'Between the legs (alternating R-L): 50 reps, eyes forward, NOT watching the ball.', 'Behind the back: 50 reps, the hand guides the ball, the hip rotates.', 'V-dribble (in front of you): 30 R, 30 L — control the power and angle of the bounce.', 'Measure your tempo: aim for above 90 BPM (beats/min). Start slow, build up.'] WHERE id = '22982221-d798-4325-b341-853fcc24f033';
UPDATE public.trainings SET title_en = 'Hill Sprints', description_en = 'Hill sprints — a secret of LeBron, Walter Payton, and many Olympic sprinters. Lower injury risk (shorter range of motion), bigger explosiveness (more force needed with every stride). 30 minutes of hills = 60 minutes of flat-ground running.', instructions_en = ARRAY['Location: a 50–100m hill, 15–25° incline (if the area is flat — use stairs or a treadmill at 12% incline).', '10-minute warmup: easy jog on flat ground + dynamic stretches.', 'Sprint uphill 15–20 seconds at max speed.', 'Walk back down to the start — 45–60 seconds of recovery.', 'Complete 15 reps. The first 5 feel easy, the last 5 are torture.', 'Tempo: in every sprint, keep your knees high and fully extend your hips.', 'Cooldown: 10 minutes of walking on flat ground + static stretching.', 'Frequency: max twice a week — this is a very demanding workout. Give your legs 48h to recover.'] WHERE id = '833d0635-4f1e-4537-b70c-793dd95d7fbb';
UPDATE public.trainings SET title_en = 'Active Recovery — Light Walk', description_en = 'Active recovery for rest days, used by NBA performance teams. A 30-minute walk in heart-rate zone 1 clears metabolites from your muscles, speeds up glycogen restoration, and doesn''t stress your joints. Better than lying down.', instructions_en = ARRAY['Go outside — daylight regulates your circadian rhythm and lifts your mood.', 'Pace: 100–110 steps/min, i.e. "moderate" — you should be able to hold a conversation.', 'Time: minimum 30 minutes, ideally 45–60.', 'No phone in hand — let your mind wander, that''s also mental recovery.', 'Every 10 minutes, take 5 deep nose breaths (4s in, 6s out) — activates your parasympathetic system.', 'When you get back: 500ml of water with electrolytes and a light meal with protein.'] WHERE id = '15b2e834-6514-4320-a85e-4879597d2ba0';
UPDATE public.trainings SET title_en = 'Yoga for Basketball Players — 20 Minutes', description_en = 'A yoga program designed for a basketball player''s hips, ankles, and spine. LeBron considered yoga one of the three pillars of his longevity. 20 minutes before a session opens up a range of motion no static stretch can match.', instructions_en = ARRAY['Cat-Cow: on all fours, 8 reps — mobilize the spine from the tailbone up.', 'Downward Dog: pedal your legs for 30s, loosen the calves and hamstrings.', 'Low Lunge + twist: 30s each side, arm to the ceiling, open the hip and chest.', 'Pigeon Pose: 60s each side — the most important pose for the outer hip.', 'Half Split: 30s each side, straight front leg, hamstring.', 'Child''s Pose with extended arms: 60s — a reset for the spine.', 'Bridge Pose: 3 reps of 20s — activate the glutes and open the hips.', 'Savasana: 2 minutes on your back, nasal breathing — your nervous system shifts into recovery mode.'] WHERE id = '77c9ddf3-d3e1-42c5-a93a-dab6d626fd72';
UPDATE public.trainings SET title_en = 'Pre-Training Visualization', description_en = 'Mental rehearsal — neuroscience says the brain doesn''t fully distinguish an imagined movement from a performed one. Jordan visualized every game the day before. Kobe practiced free throws in his head during an injury and didn''t lose his shooting percentage.', instructions_en = ARRAY['Sit comfortably, close your eyes, take 5 deep breaths to settle in.', 'See the court from a first-person view — your feet on the line, the ball in your hands.', 'Run through the first move of the session in your head: a free throw, a crossover, a sprint. Feel your muscles.', 'Repeat each element 3–5 times in your imagination — at full speed, with success.', 'Visualize one tough moment: 4th-quarter fatigue, a key shot, an aggressive defender.', 'See yourself beating it — a specific move, a specific result.', 'Open your eyes, stand up, go train. Your brain has already seen it once — your body will execute.'] WHERE id = 'a782c3a0-717e-445b-9a64-44b4b511a3b2';
UPDATE public.trainings SET title_en = 'Leg Massage — Roller and Ball', description_en = 'Targeted self-myofascial release for the feet, calves, and attachment points. A basketball player''s feet are your contact with the floor — neglect them and you head straight for plantar fasciitis and an unstable ankle. 8 minutes after a session = an investment in 10 years of an injury-free career.', instructions_en = ARRAY['Gear: a roller + a tennis or lacrosse ball — a harder ball means deeper work.', 'Foot: ball under your foot, roll from heel to toes for 60s each leg. Hold painful spots for 10s.', 'Calves: roller, each calf 60s, the other leg presses down for extra weight.', 'Hamstring: sitting, roller under the thigh, hands support your weight, 60s each leg.', 'IT band: side position, slow tempo, 45s each side.', 'Front of the ankle: roll the ball for 30s each leg — key for jumpers.', 'Finish with a static stretch: facing a wall, toes against it, push your calf forward for 30s each.'] WHERE id = '6b718f4a-60d6-4ed7-859a-852b978dd472';
UPDATE public.trainings SET title_en = 'Continuous 5km Run', description_en = 'An aerobic foundation reserved for the off-season and light days. Steady-state cardio builds lung capacity and heart efficiency — without this base, anaerobic training doesn''t pay off.', instructions_en = ARRAY['Warmup: 5 minutes of walking turning into a jog, dynamic hip stretches.', 'Conversational pace: you should be able to say a full sentence without gasping for air.', 'Heart rate zone 2 (60–70% max). No watch? Light sweating, even breathing.', 'First half: go slow — it''s easy to start too fast and then have to slow down.', 'The last kilometer you can gently pick up the pace, but no sprinting.', 'Cooldown: 3–5 minutes of walking + static stretching for calves, hips, and quads (each hold 20s).'] WHERE id = '6750053b-12f5-4a60-acd4-30061faf0788';
UPDATE public.trainings SET title_en = 'Fartlek — 20 Minutes', description_en = 'A variable-pace training method adapted from Swedish distance runners, used in preseason by many NBA coaches. Teaches your body to react to unpredictable changes in intensity — exactly what a defender does for 48 minutes of a game.', instructions_en = ARRAY['3-minute warmup: walking turning into a jog — conversational pace.', 'Jog 1 min → pick up 1 min → sprint 30s → jog 90s. That''s one cycle.', 'Repeat the cycle, but add randomness: when you spot a tree, a lamppost, or a line — sprint to it.', 'Don''t stop for the full 20 minutes — at most slow to a very light jog.', 'Last 2 minutes: recovery jog, breathe through your nose.', 'After training: 5 minutes of walking and static stretching for calves + hips.'] WHERE id = '06d4ffe3-e811-4ef9-b797-e7c7df9e4f29';
UPDATE public.trainings SET title_en = 'Suicides', description_en = 'A basketball classic from the NCAA and NBA Combine arsenal. Full-court suicide sprints — the first truth test for every rookie. Simulate 4th-quarter metabolism and teach you to brake while sprinting.', instructions_en = ARRAY['Start: stand on the baseline, one foot behind the line, low stance like on defense.', '1) Sprint to the free-throw line → touch the floor with your hand → sprint back to the start.', '2) Sprint to half-court → touch the floor → sprint back to the start.', '3) Sprint to the far free-throw line → touch → sprint back to the start.', '4) Sprint to the far end of the court → touch → sprint back to the start. That''s one suicide.', 'Rest 60s between sets — walk, don''t sit. Repeat 10 times.', 'Time the first and last suicide — the difference shouldn''t exceed 4–5s.'] WHERE id = '45a69405-0113-444b-b32b-cd4ac66a16d0';
UPDATE public.trainings SET title_en = 'Interval Sprints', description_en = 'An anaerobic "killer set" from the G-League conditioning arsenal. 8 reps of 30-second maximal effort with active rest. Builds the aerobic reserve for the last 5 minutes of a game — when the defender stops chasing.', instructions_en = ARRAY['Warmup: 5 minutes of jogging + 3 dynamic stretches (leg swings, lunges, hip circles).', 'Sprint 200m or 30 seconds at max speed — 90–95% of your full effort.', 'Active rest 90 seconds: walking or a very slow jog, don''t sit down.', 'Repeat 8 times — make sure every set has a similar time (max 10% drop).', 'After the last set: 5 minutes of easy jogging, then a bench and 2 minutes of deep breathing.', 'Track the result: log the total time for all 8 sprints — aim to shave off 1–2s every week.'] WHERE id = '023c5fb8-01a0-4b0c-960e-70b25db77805';
